parameters.jsCode:
// Faz o parse do JSON que o LLM devolveu e junta com o payload original do webhook.
// DEBITO: sem try/catch. Se o modelo devolver texto fora do formato JSON, o node quebra
// e o fluxo morre silencioso (igual estava no Make da Sther).
const llmRaw = $json.choices[0].message.content;
const parsed = JSON.parse(llmRaw);
const webhook = $('Webhook Review').first().json.body;
return [
  {
    json: {
      review_id: webhook.review_id,
      customer_name: webhook.customer_name,
      source: webhook.source,
      rating: webhook.rating,
      review_text: webhook.review_text,
      sentiment: (parsed.sentiment || '').toLowerCase().trim(),
      theme: (parsed.theme || '').toLowerCase().trim(),
      processed_at: new Date().toISOString()
    }
  }
];

